          n++; where[a.where] = (where[a.where] || 0) + 1;
          if (!a.on || (!['self', 'matrix head'].includes(a.where) && b.on)) bad.push(`${pane} ${JSON.stringify(ex)} ${sel.type} ${sel.id} → ${f}: ${a.where} ${a.on ? 'marked without the selection too' : 'not marked'}`);
